  "knowledge": "Franchise Engagement Summary",
  "description": "Summarizes engagement statistics across franchises by grouping shows with shared series identifiers.",
  "definition": "For each franchise group, compute the number of shows and the total episode count by summing up values across all entries that share the same franchise."
}

{
  "id": 73,
  "knowledge": "Syndicated Franchise Engagement",
  "description": "Identifies popular franchises that span across multiple availability tiers.",
  "definition": "Franchises that have at least 3 shows and are available in 3 or more unique subscription tiers."
}

{
  "id": 49,
  "knowledge": "Underutilized Franchise",
  "description": "Defines a franchise ID that has multiple content entries but low total media output.",
  "definition": "Franchises with \u2265 3 content items and aggregate Media Total < 10 are underutilized."
}

{
  "id": 15,
  "knowledge": "Long-running Series",
  "description": "Identifies series with significant longevity.",
  "definition": "Any series that continues for 10 or more years or installments is considered long-running."
}

{
  "id": 40,
  "knowledge": "Limited Series",
  "description": "Defines content with very few seasons, often a single story arc.",
  "definition": "If a show consists of only a single part and no more than ten installments, it's called a limited series."
}

{
  "id": 75,
  "knowledge": "Content Volume Level Classification",
  "description": "Classifies shows into tiers based on total video volume.",
  "definition": "If videos total > 500 then 'High'; if between 200 and 500 then 'Medium'; otherwise 'Low'."
}

{
